class Store:
    def __init__(self):
        self._data = {}

    def incr(self, key, now):
        """Increment key's counter; first hit opens the window."""
        entry = self._data.get(key)
        if entry is None:
            self._data[key] = {"count": 1, "expires_at": now + self.window_seconds()}
            return 1
        entry["count"] += 1
        entry["expires_at"] = now + self.window_seconds()
        return entry["count"]

    def get(self, key, now):
        entry = self._data.get(key)
        if entry is None or entry["expires_at"] <= now:
            return 0
        return entry["count"]

    def window_seconds(self):
        import config
        return config.WINDOW_SECONDS

    def sweep(self, now):
        stale = [k for k, v in self._data.items() if v["expires_at"] <= now]
        for k in stale:
            del self._data[k]
        return len(stale)

